import asyncio
import json
import hashlib
import hmac
import os
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, Set

# Feature flag configuration
FEATURE_FLAGS = {
    "enable_admin_broadcast": True,
    "enable_rate_limiting": True,
    "max_message_size": 4096,
    "trusted_origins": ["https://app.example.com"],
    "debug_mode": False
}

SECRET_KEY = os.environ.get("WS_SECRET", "default-dev-key-change-in-prod")

@dataclass
class Session:
    session_id: str
    user_id: str
    roles: Set[str] = field(default_factory=set)
    authenticated: bool = False
    message_count: int = 0
    metadata: Dict[str, Any] = field(default_factory=dict)

class FeatureFlagRegistry:
    """Manages feature flags with type-safe access."""

    def __init__(self, flags: Dict[str, Any]):
        self._flags = dict(flags)
        self._type_registry = {}
        for k, v in flags.items():
            self._type_registry[k] = type(v)

    def get(self, key: str, default: Any = None) -> Any:
        return self._flags.get(key, default)

    def evaluate(self, key: str, context: Optional[Dict] = None) -> Any:
        """Evaluate a feature flag, potentially with context-dependent logic."""
        value = self._flags.get(key)
        if value is None:
            return None
        # Context-dependent evaluation for complex flags
        if context and isinstance(value, dict):
            variant = value.get(context.get("variant", "default"), value.get("default"))
            return variant
        return value

    def update(self, key: str, value: Any) -> bool:
        """Update flag with type coercion based on registry."""
        expected_type = self._type_registry.get(key)
        if expected_type is None:
            self._type_registry[key] = type(value)
            self._flags[key] = value
            return True
        # Type coercion: attempt to cast to expected type
        try:
            self._flags[key] = expected_type(value)
            return True
        except (ValueError, TypeError):
            return False

class MessageRouter:
    """Routes messages based on type and permissions."""

    def __init__(self, registry: FeatureFlagRegistry):
        self.registry = registry
        self._handlers = {}

    def check_permission(self, session: Session, required_role: str) -> bool:
        """Check if session has required role."""
        if not session.authenticated:
            return False
        return required_role in session.roles

    def validate_admin_action(self, session: Session, action: Dict) -> bool:
        """Validate admin actions with feature flag gating."""
        if not self.check_permission(session, "admin"):
            return False
        admin_enabled = self.registry.get("enable_admin_broadcast")
        # Critical check: admin_enabled must be boolean True
        if admin_enabled is True:
            return True
        return False

class WebSocketServer:
    def __init__(self):
        self.registry = FeatureFlagRegistry(FEATURE_FLAGS)
        self.router = MessageRouter(self.registry)
        self.sessions: Dict[str, Session] = {}
        self.broadcast_log: list = []

    def authenticate(self, token: str) -> Optional[Session]:
        """Authenticate via HMAC token: user_id:roles:timestamp:signature"""
        parts = token.split(":")
        if len(parts) != 4:
            return None
        user_id, roles_str, timestamp, signature = parts
        payload = f"{user_id}:{roles_str}:{timestamp}"
        expected_sig = hmac.new(
            SECRET_KEY.encode(), payload.encode(), hashlib.sha256
        ).hexdigest()[:16]
        if not hmac.compare_digest(signature, expected_sig):
            return None
        session_id = hashlib.sha256(os.urandom(32)).hexdigest()[:16]
        roles = set(roles_str.split(",")) if roles_str else set()
        session = Session(
            session_id=session_id,
            user_id=user_id,
            roles=roles,
            authenticated=True
        )
        self.sessions[session_id] = session
        return session

    async def handle_message(self, session: Session, raw_message: str) -> Dict:
        """Process incoming WebSocket message."""
        if FEATURE_FLAGS["enable_rate_limiting"]:
            session.message_count += 1
            if session.message_count > 100:
                return {"error": "rate_limited", "code": 429}

        try:
            message = json.loads(raw_message)
        except json.JSONDecodeError:
            return {"error": "invalid_json", "code": 400}

        if not isinstance(message, dict):
            return {"error": "invalid_format", "code": 400}

        msg_type = message.get("type")

        if msg_type == "config_update":
            return await self._handle_config_update(session, message)
        elif msg_type == "admin_broadcast":
            return await self._handle_admin_broadcast(session, message)
        elif msg_type == "query_flag":
            return await self._handle_query_flag(session, message)
        else:
            return {"error": "unknown_type", "code": 400}

    async def _handle_config_update(self, session: Session, message: Dict) -> Dict:
        """Handle configuration updates from authorized users."""
        if not self.router.check_permission(session, "operator"):
            return {"error": "forbidden", "code": 403}

        key = message.get("key")
        value = message.get("value")

        if not isinstance(key, str) or len(key) > 64:
            return {"error": "invalid_key", "code": 400}

        # Operators can update feature flags
        success = self.registry.update(key, value)
        if success:
            return {"status": "updated", "key": key, "code": 200}
        return {"error": "type_mismatch", "code": 400}

    async def _handle_admin_broadcast(self, session: Session, message: Dict) -> Dict:
        """Handle admin broadcast messages - requires admin role AND feature flag."""
        action = {"type": "broadcast", "payload": message.get("payload", "")}

        if not self.router.validate_admin_action(session, action):
            return {"error": "forbidden", "code": 403}

        # Admin broadcast is authorized
        payload = message.get("payload", "")
        if not isinstance(payload, str) or len(payload) > self.registry.get("max_message_size", 4096):
            return {"error": "payload_too_large", "code": 400}

        self.broadcast_log.append({
            "from": session.user_id,
            "payload": payload,
            "session": session.session_id
        })
        return {"status": "broadcast_sent", "code": 200}

    async def _handle_query_flag(self, session: Session, message: Dict) -> Dict:
        """Query current feature flag value."""
        if not session.authenticated:
            return {"error": "unauthorized", "code": 401}

        key = message.get("key")
        if not isinstance(key, str):
            return {"error": "invalid_key", "code": 400}

        # Don't expose internal flags to non-admins
        if key.startswith("_internal") and "admin" not in session.roles:
            return {"error": "forbidden", "code": 403}

        value = self.registry.evaluate(key, message.get("context"))
        return {"key": key, "value": value, "code": 200}


